// Der Zeitraum wird einmal zentral bestimmt und an alle Quellen weitergereicht.
// Wuerde jede Quelle selbst rechnen, verschieben sich die Fenster um einen Tag,
// sobald der Lauf einmal nachts haengen bleibt - und der Vorwochenvergleich
// vergleicht Aepfel mit Birnen.

function montagVor(wochen, bezug) {
  const d = new Date(bezug);
  d.setUTCHours(0, 0, 0, 0);
  const wochentag = (d.getUTCDay() + 6) % 7;   // Montag = 0, Sonntag = 6
  d.setUTCDate(d.getUTCDate() - wochentag - wochen * 7);
  return d;
}

function iso(d) {
  return d.toISOString().slice(0, 10);
}

function de(d) {
  return String(d.getUTCDate()).padStart(2, '0') + '.' + String(d.getUTCMonth() + 1).padStart(2, '0') + '.' + d.getUTCFullYear();
}

const heute = new Date();
const startWoche = montagVor(1, heute);              // Montag der abgeschlossenen Woche
const endeWoche = new Date(startWoche); endeWoche.setUTCDate(endeWoche.getUTCDate() + 6);
const startVorwoche = montagVor(2, heute);
const endeVorwoche = new Date(startVorwoche); endeVorwoche.setUTCDate(endeVorwoche.getUTCDate() + 6);

return [{
  json: {
    woche_von: iso(startWoche),
    woche_bis: iso(endeWoche),
    vorwoche_von: iso(startVorwoche),
    vorwoche_bis: iso(endeVorwoche),
    zeitraum_label: de(startWoche) + ' bis ' + de(endeWoche),
    vorwoche_label: de(startVorwoche) + ' bis ' + de(endeVorwoche),
    kalenderwoche: Math.ceil(((startWoche - new Date(Date.UTC(startWoche.getUTCFullYear(), 0, 1))) / 86400000 + 1) / 7),
  },
}];

// Beide Quellen werden hier bewusst ueber ihren Node-Namen geholt und nicht ueber
// $input: nach dem Merge liegen die Datensaetze sonst vermischt vor und man kann
// Umsatzzeilen nicht mehr von Angebotszeilen unterscheiden.

const UMSATZ_AUFFAELLIG_PROZENT = 15;   // ab hier gehoert die Abweichung in den Kommentar
const ANGEBOT_ALT_TAGE = 30;

function alsBetrag(wert) {
  if (typeof wert === 'number') return wert;
  const s = String(wert ?? '').replace(/[^0-9,.\-]/g, '');
  if (!s) return 0;
  return Number(s.replace(/\./g, '').replace(',', '.')) || 0;
}

// Sheets liefert TT.MM.JJJJ, APIs liefern ISO. Beides muss vergleichbar werden,
// sonst ist jede Zeitraumabgrenzung Zufall.
function alsIso(wert) {
  if (!wert) return null;
  const s = String(wert).trim();
  const de = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  if (de) return de[3] + '-' + de[2].padStart(2, '0') + '-' + de[1].padStart(2, '0');
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}

function imZeitraum(datum, von, bis) {
  return Boolean(datum) && datum >= von && datum <= bis;
}

function prozentAenderung(neu, alt) {
  // Division durch Null bei fehlender Vorwoche abfangen - sonst steht "Infinity"
  // im Bericht der Geschaeftsfuehrung.
  if (!alt) return null;
  return Number((((neu - alt) / alt) * 100).toFixed(1));
}

const z = $('Berichtszeitraum bestimmen').first().json;
const umsatzZeilen = $('Umsaetze aus Google Sheets').all().map((e) => e.json);

// Die API-Antwort kann als Liste, unter .angebote oder unter .data kommen -
// alle drei Faelle abfangen, statt beim ersten Formatwechsel zu scheitern.
const antwort = $('Angebote aus Warenwirtschaft holen').first().json;
const rumpf = antwort?.body ?? antwort;
const statusCode = Number(antwort?.statusCode ?? 200);
const angebote = Array.isArray(rumpf) ? rumpf : (rumpf?.angebote ?? rumpf?.data ?? []);
const angeboteOk = statusCode < 400 && Array.isArray(angebote);

function umsatzSumme(von, bis) {
  return umsatzZeilen
    .filter((r) => imZeitraum(alsIso(r['Datum']), von, bis))
    .reduce((s, r) => s + alsBetrag(r['Betrag']), 0);
}

function umsatzAnzahl(von, bis) {
  return umsatzZeilen.filter((r) => imZeitraum(alsIso(r['Datum']), von, bis)).length;
}

const umsatz = Number(umsatzSumme(z.woche_von, z.woche_bis).toFixed(2));
const umsatzVor = Number(umsatzSumme(z.vorwoche_von, z.vorwoche_bis).toFixed(2));
const anzahl = umsatzAnzahl(z.woche_von, z.woche_bis);
const anzahlVor = umsatzAnzahl(z.vorwoche_von, z.vorwoche_bis);

const heute = new Date();
const alleAngebote = angeboteOk ? angebote.map((a) => ({
  datum: alsIso(a.datum ?? a.erstellt_am ?? a.date),
  betrag: alsBetrag(a.betrag ?? a.summe ?? a.amount),
  status: String(a.status ?? '').toLowerCase(),
})) : [];

const offen = alleAngebote.filter((a) => a.status.startsWith('offen'));
const alt = offen.filter((a) => a.datum && (heute - new Date(a.datum)) / 86400000 > ANGEBOT_ALT_TAGE);

function conversion(von, bis) {
  const entschieden = alleAngebote.filter((a) => imZeitraum(a.datum, von, bis) && (a.status.startsWith('gewonnen') || a.status.startsWith('verloren')));
  if (!entschieden.length) return null;
  const gewonnen = entschieden.filter((a) => a.status.startsWith('gewonnen')).length;
  return Number(((gewonnen / entschieden.length) * 100).toFixed(1));
}

const conv = conversion(z.woche_von, z.woche_bis);
const convVor = conversion(z.vorwoche_von, z.vorwoche_bis);
const umsatzDelta = prozentAenderung(umsatz, umsatzVor);

// Die Auffaelligkeiten werden hier berechnet und nicht der KI ueberlassen: was
// als auffaellig gilt, ist eine betriebliche Entscheidung, keine sprachliche.
const auffaelligkeiten = [];
if (umsatzDelta !== null && Math.abs(umsatzDelta) >= UMSATZ_AUFFAELLIG_PROZENT) {
  auffaelligkeiten.push('Umsatz ' + (umsatzDelta > 0 ? 'plus' : 'minus') + ' ' + Math.abs(umsatzDelta) + ' Prozent gegenueber der Vorwoche');
}
if (umsatzVor > 0 && umsatz === 0) {
  auffaelligkeiten.push('In der Berichtswoche wurde kein Umsatz verbucht - moeglicherweise fehlen Rechnungen im Sheet');
}
if (alt.length) {
  auffaelligkeiten.push(alt.length + ' Angebote liegen laenger als ' + ANGEBOT_ALT_TAGE + ' Tage unbeantwortet');
}
if (conv !== null && convVor !== null && Math.abs(conv - convVor) >= 10) {
  auffaelligkeiten.push('Conversion veraendert sich um ' + (conv - convVor).toFixed(1) + ' Prozentpunkte');
}
if (anzahl && umsatz / anzahl > 0 && anzahlVor && (umsatz / anzahl) > (umsatzVor / anzahlVor) * 2) {
  auffaelligkeiten.push('Der durchschnittliche Rechnungsbetrag hat sich mehr als verdoppelt - vermutlich ein Grossauftrag');
}

return [{
  json: {
    zeitraum_label: z.zeitraum_label,
    vorwoche_label: z.vorwoche_label,
    kalenderwoche: z.kalenderwoche,
    umsatz_eur: umsatz,
    umsatz_vorwoche_eur: umsatzVor,
    umsatz_veraenderung_prozent: umsatzDelta,
    anzahl_rechnungen: anzahl,
    anzahl_rechnungen_vorwoche: anzahlVor,
    durchschnittsbetrag_eur: anzahl ? Number((umsatz / anzahl).toFixed(2)) : 0,
    offene_angebote: offen.length,
    offenes_angebotsvolumen_eur: Number(offen.reduce((s, a) => s + a.betrag, 0).toFixed(2)),
    offene_angebote_ueber_30_tage: alt.length,
    conversion_prozent: conv,
    conversion_vorwoche_prozent: convVor,
    auffaelligkeiten,
    datenbasis_ok: umsatzZeilen.length > 0 && angeboteOk,
    datenluecke: [
      umsatzZeilen.length ? null : 'Google Sheet "Umsaetze" lieferte keine Zeilen',
      angeboteOk ? null : 'Warenwirtschafts-API antwortete mit Status ' + statusCode + ' oder in unerwartetem Format',
    ].filter(Boolean).join('; '),
  },
}];

// Der Kommentar kommt je nach Zweig aus dem KI-Node oder aus dem Set-Node, und
// die OpenAI-Node liefert ihn je nach Einstellung unter content, message.content
// oder text. Alle Varianten abfangen ist billiger als ein leerer Bericht.
const q = $input.first().json;
const kommentar = q.kommentar ?? q.message?.content ?? q.content ?? q.text ?? '(kein Kommentar erzeugt)';
const k = $('Kennzahlen berechnen').first().json;

function eur(wert) {
  return Number(wert || 0).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' EUR';
}

function delta(wert) {
  if (wert === null || wert === undefined) return 'kein Vergleichswert';
  return (wert > 0 ? '+' : '') + wert + ' %';
}

function prozent(wert) {
  return wert === null || wert === undefined ? 'nicht berechenbar' : wert + ' %';
}

const zeilen = [
  'Wochenbericht KW ' + k.kalenderwoche + ' (' + k.zeitraum_label + ')',
  'Vergleichswoche: ' + k.vorwoche_label,
  '',
  'Umsatz                       ' + eur(k.umsatz_eur) + '   (' + delta(k.umsatz_veraenderung_prozent) + ')',
  'Rechnungen                   ' + k.anzahl_rechnungen + '   (Vorwoche: ' + k.anzahl_rechnungen_vorwoche + ')',
  'Durchschnittlicher Beleg     ' + eur(k.durchschnittsbetrag_eur),
  'Offene Angebote              ' + k.offene_angebote + '   Volumen: ' + eur(k.offenes_angebotsvolumen_eur),
  'davon aelter als 30 Tage     ' + k.offene_angebote_ueber_30_tage,
  'Conversion                   ' + prozent(k.conversion_prozent) + '   (Vorwoche: ' + prozent(k.conversion_vorwoche_prozent) + ')',
  '',
  'Auffaelligkeiten:',
  k.auffaelligkeiten.length ? k.auffaelligkeiten.map((a) => '- ' + a).join('\n') : '- keine oberhalb der eingestellten Schwellen',
  '',
  'Kommentar:',
  kommentar,
  '',
  '--',
  'Automatisch erstellt. Der Kommentar wurde maschinell mit einem KI-Sprachmodell formuliert (Kennzeichnung nach Art. 50 EU-AI-Act), die Kennzahlen stammen unveraendert aus Google Sheets und der Warenwirtschaft.',
];

return [{ json: { betreff: 'Wochenbericht KW ' + k.kalenderwoche + ' - Umsatz ' + eur(k.umsatz_eur) + ' (' + delta(k.umsatz_veraenderung_prozent) + ')', text: zeilen.join('\n') } }];
